export const ENEMY_REWARDS = Object.freeze({
  sentinel: Object.freeze({ xp: 120, gold: 35 }),
  boss: Object.freeze({ xp: 240, gold: 150 }),
  ...Object.fromEntries(ENEMY_ARCHETYPES.map(({ id, rewardXp, rewardGold }) => [
    id,
    Object.freeze({ xp: rewardXp, gold: rewardGold }),
  ])),
})

export const ENEMY_ARCHETYPE_BY_ID = new Map(ENEMY_ARCHETYPES.map((archetype) => [archetype.id, archetype]))

export function getEnemyArchetype(id) {
  return ENEMY_ARCHETYPE_BY_ID.get(id) ?? null
}
